//! @file
//!
//! @brief Carbonite Robin-hood Unordered Multi-map container.
#pragma once

#include "RobinHoodImpl.h"

#include <functional> // for std::hash
#include <type_traits>
#include <utility>

namespace carb::container
{

/**
 * Implements an Unordered Multimap, that is: a container that contains a mapping of keys to values where keys may be
 * inserted multiple times, each creating a new element. There is no defined order to the set of keys.
 *
 * \copydetails detail::RobinHood
 *
 * @warning This container is similar to, but not a drop-in replacement for `std::unordered_multimap` due to differences
 * in iterator invalidation and memory layout.
 *
 * Iterator/reference/pointer invalidation (note differences from `std::unordered_multimap`):
 * Operation | Invalidates
 * --------- | -----------
 * All read operations | Never
 * `clear`, `rehash`, `reserve`, `operator=`, `insert`, `emplace` | Always
 * `erase` | Only the element removed
 * `swap` | All iterators, no pointers/references
 *
 * @tparam Key The key type
 * @tparam Value The mapped type to be associated with `Key`
 * @tparam Hasher A functor to use as a hashing function for \c Key
 * @tparam Equals A functor to use to compare two \c Key values for equality
 * @tparam LoadFactorMax100 The load factor to use for the table. This value must be in the range `[10, 100]` and
 *   represents the percentage of entries in the hash table that will be filled before resizing. Open-addressing hash
 *   maps with 100% usage have better memory usage but worse performance since they need "gaps" in the hash table to
 *   terminate runs. The default value is \ref kDefaultLoadFactor.
 * @tparam Allocator The Allocator to use. Must support rebind.
 */
template <typename Key,
          typename Value,
          typename Hasher = std::hash<Key>,
          typename Equals = std::equal_to<Key>,
          size_t LoadFactorMax100 = kDefaultLoadFactor,
          typename Allocator = std::allocator<std::pair<const Key, Value>>>
class RHUnorderedMultimap
    : public detail::RobinHood<detail::RobinHoodMapTraits<Key, Value, Hasher, Equals, Allocator, LoadFactorMax100>>
{
    using Base = detail::RobinHood<detail::RobinHoodMapTraits<Key, Value, Hasher, Equals, Allocator, LoadFactorMax100>>;

    static_assert(std::is_same_v<typename Allocator::value_type, std::pair<const Key, Value>>,
                  "Allocator::value_type must match std::pair<const Key, Value>");

public:
    //! The key type
    using key_type = typename Base::key_type;
    //! The mapped value type
    using mapped_type = Value;
    //! The value type (effectively `std::pair<const key_type, mapped_type>`)
    using value_type = typename Base::value_type;
    //! Unsigned integer type (typically \c size_t)
    using size_type = typename Base::size_type;
    //! Signed integer type (typically \c ptrdiff_t)
    using difference_type = typename Base::difference_type;
    //! The hash function
    using hasher = typename Base::hasher;
    //! The key-equals function
    using key_equal = typename Base::key_equal;
    //! \c value_type&
    using reference = typename Base::reference;
    //! `const value_type&`
    using const_reference = typename Base::const_reference;
    //! \c value_type*
    using pointer = typename Base::pointer;
    //! `const value_type*`
    using const_pointer = typename Base::const_pointer;
    //! A \a LegacyForwardIterator to \c value_type
    using iterator = typename Base::iterator;
    //! A \a LegacyForwardIterator to `const value_type`
    using const_iterator = typename Base::const_iterator;
    //! A \a LegacyForwardIterator to \c value_type that proceeds to the next matching key when incremented.
    using find_iterator = typename Base::find_iterator;
    //! A \a LegacyForwardIterator to `const value_type` that proceeds to the next matching key when incremented.
    using const_find_iterator = typename Base::const_find_iterator;
    //! The Allocator
    using allocator_type = typename Base::allocator_type;

    //! The container's LoadFactor.
    constexpr static size_t LoadFactor = Base::LoadFactor;

private:
    // MSVC has an internal compiler error or other errors if we try using Base::IsTransparent_v or use it directly.
    template <typename T>
    constexpr static bool IsTransparent_v =
        detail::dependent_bool<detail::SupportsTransparent<key_type, hasher, key_equal>, T>::value;

public:
    /**
     * Constructs empty container.
     */
    constexpr RHUnorderedMultimap() noexcept = default;


    /**
     * Constructor with reservation hint.
     * @param reserved Minimal number of slots to reserve on initialization.
     * @param h Hash function to use.
     * @param ke Comparison function to use for all key comparisons of this container.
     * @param al Allocator to use for all memory allocations of this container.
     */
    explicit RHUnorderedMultimap(size_type reserved,
                                 const hasher& h = hasher(),
                                 const key_equal& ke = key_equal(),
                                 const allocator_type& al = allocator_type())
        : Base(reserved, h, ke, al)
    {
    }

    /**
     * Constructor with reservation hint and allocator.
     * @param reserved Minimal number of slots to reserve on initialization.
     * @param al Allocator to use for all memory allocations of this container.
     */
    RHUnorderedMultimap(size_type reserved, const allocator_type& al)
        : RHUnorderedMultimap(reserved, hasher(), key_equal(), al)
    {
    }

    /**
     * Constructor with reservation hint, hash function and allocator.
     * @param reserved Minimal number of slots to reserve on initialization.
     * @param h Hash function to use.
     * @param al Allocator to use for all memory allocations of this container.
     */
    RHUnorderedMultimap(size_type reserved, const hasher& h, const allocator_type& al)
        : RHUnorderedMultimap(reserved, h, key_equal(), al)
    {
    }

    /**
     * Constructor with allocator.
     * @param al Allocator to use for all memory allocations of this container.
     */
    explicit RHUnorderedMultimap(const allocator_type& al) : Base(al)
    {
    }

    /**
     * Constructs the container with the contents of range [first, last).
     * @param first The first iterator defining the source range of elements to copy.
     * @param last The last iterator defining the source range of elements to copy.
     * @param reserved A hint to the minimal number of slots to reserve.
     * @param h Hash function to use.
     * @param ke Comparison function to use for all key comparisons of this container.
     * @param al Allocator to use for all memory allocations of this container.
     */
    template <class InputIt>
    RHUnorderedMultimap(InputIt first,
                        InputIt last,
                        size_type reserved = 0,
                        const hasher& h = hasher(),
                        const key_equal& ke = key_equal(),
                        const allocator_type& al = allocator_type())
        : RHUnorderedMultimap(reserved, h, ke, al)
    {
        // Since first and last are input iterators, we only get one iteration through the list and cannot measure it.
        while (first != last)
            insert(*(first++));
    }

    /**
     * Constructs the container with the contents of range [first, last).
     * @param first The first iterator defining the source range of elements to copy.
     * @param last The last iterator defining the source range of elements to copy.
     * @param reserved A hint to the minimal number of slots to reserve.
     * @param al Allocator to use for all memory allocations of this container.
     */
    template <class InputIt>
    RHUnorderedMultimap(InputIt first, InputIt last, size_type reserved, const allocator_type& al)
        : RHUnorderedMultimap(reserved, hasher(), key_equal(), al)
    {
        // Since first and last are input iterators, we only get one iteration through the list and cannot measure it.
        while (first != last)
            insert(*(first++));
    }

    /**
     * Constructs the container with the contents of range [first, last).
     * @param first The first iterator defining the source range of elements to copy.
     * @param last The last iterator defining the source range of elements to copy.
     * @param reserved A hint to the minimal number of slots to reserve.
     * @param h Hash function to use.
     * @param al Allocator to use for all memory allocations of this container.
     */
    template <class InputIt>
    RHUnorderedMultimap(InputIt first, InputIt last, size_type reserved, const hasher& h, const allocator_type& al)
        : RHUnorderedMultimap(reserved, h, key_equal(), al)
    {
        // Since first and last are input iterators, we only get one iteration through the list and cannot measure it.
        while (first != last)
            insert(*(first++));
    }

    /**
     * Constructs the container with the contents of items from an initializer_list.
     * @param init initializer list to initialize the elements of the container with.
     * @param reserved A hint to the minimal number of slots to reserve. If not specified, `init.size()` is used.
     * @param h Hash function to use.
     * @param ke Comparison function to use for all key comparisons of this container.
     * @param al Allocator to use for all memory allocations of this container.
     */
    RHUnorderedMultimap(std::initializer_list<value_type> init,
                        size_type reserved = 0,
                        const hasher& h = hasher(),
                        const key_equal& ke = key_equal(),
                        const allocator_type& al = allocator_type())
        : RHUnorderedMultimap(reserved ? reserved : init.size(), h, ke, al)
    {
        for (auto& val : init)
            insert(val);
    }

    /**
     * Constructs the container with the contents of items from an initializer_list.
     * @param init initializer list to initialize the elements of the container with.
     * @param reserved A hint to the minimal number of slots to reserve.
     * @param al Allocator to use for all memory allocations of this container.
     */
    RHUnorderedMultimap(std::initializer_list<value_type> init, size_type reserved, const allocator_type& al)
        : RHUnorderedMultimap(init, reserved, hasher(), key_equal(), al)
    {
    }

    /**
     * Constructs the container with the contents of items from an initializer_list.
     * @param init initializer list to initialize the elements of the container with.
     * @param reserved A hint to the minimal number of slots to reserve.
     * @param h Hash function to use.
     * @param al Allocator to use for all memory allocations of this container.
     */
    RHUnorderedMultimap(std::initializer_list<value_type> init,
                        size_type reserved,
                        const hasher& h,
                        const allocator_type& al)
        : RHUnorderedMultimap(init, reserved, h, key_equal(), al)
    {
    }

    /**
     * Copy constructor. Copies elements from another container.
     *
     * @note \c *this may have a different \c capacity() than \p other.
     * @par Complexity
     * Linear in size of @p other.
     * @param other The other container to copy entries from.
     */
    RHUnorderedMultimap(const RHUnorderedMultimap& other) : Base(other)
    {
    }

    /**
     * Copy constructor. Copies elements from another container.
     *
     * @note \c *this may have a different \c capacity() than \p other.
     * @par Complexity
     * Linear in size of @p other.
     * @param other The other container to copy entries from.
     * @param alloc The allocator to use for all memory allocations of this container.
     */
    RHUnorderedMultimap(const RHUnorderedMultimap& other, const Allocator& alloc) : Base(other, alloc)
    {
    }

    /**
     * Move constructor. Moves elements from another container.
     *
     * @note No move constructors on contained elements are invoked. \p other will be
     *       \c empty() after this operation.
     * @par Complexity
     * Constant.
     * @param other The other container to move entries from.
     */
    RHUnorderedMultimap(RHUnorderedMultimap&& other) : Base(std::move(other))
    {
    }

    /**
     * Move constructor. Moves elements from another container.
     *
     * @note No move constructors on contained elements are invoked. \p other will be
     *       \c empty() after this operation.
     * @par Complexity
     * Constant. If @p alloc is not equal to `other.get_allocator()`, then linear.
     * @param other The other container to move entries from.
     * @param alloc The Allocator to use for all memory allocations of this container.
     */
    RHUnorderedMultimap(RHUnorderedMultimap&& other, const Allocator& alloc) : Base(std::move(other), alloc)
    {
    }

    /**
     * Destructor. Destroys all contained elements and frees memory.
     */
    ~RHUnorderedMultimap() = default;

    /**
     * Copy-assign operator. Destroys all currently stored elements and copies elements from another container.
     *
     * @param other The other container to copy entries from.
     * @returns \c *this
     */
    RHUnorderedMultimap& operator=(const RHUnorderedMultimap& other)
    {
        Base::operator=(other);
        return *this;
    }

    /**
     * Move-assign operator. Effectively swaps with another container.
     *
     * @param other The other container to copy entries from.
     * @returns \c *this
     */
    RHUnorderedMultimap& operator=(RHUnorderedMultimap&& other)
    {
        Base::operator=(std::move(other));
        return *this;
    }

    /**
     * Inserts an element into the container.
     *
     * All iterators, references and pointers are invalidated.
     *
     * @param value The value to insert by copying.
     * @returns an \c iterator to the inserted element.
     */
    iterator insert(const value_type& value)
    {
        return this->insert_multi(value);
    }

    /**
     * Inserts an element into the container.
     *
     * All iterators, references and pointers are invalidated.
     *
     * @param value The value to insert by moving.
     * @returns an \c iterator to the inserted element.
     */
    iterator insert(value_type&& value)
    {
        return this->insert_multi(std::move(value));
    }

    /**
     * Inserts an element into the container. Only participates in overload resolution if
     * `std::is_constructible_v<value_type, P&&>` is true.
     *
     * All iterators, references and pointers are invalidated.
     *
     * @param value The value to insert by constructing via `std::forward<P>(value)`.
     * @returns an \c iterator to the inserted element.
     */
    template <typename P>
    iterator insert(std::enable_if_t<std::is_constructible<value_type, P&&>::value, P&&> value)
    {
        return insert(value_type{ std::forward<P>(value) });
    }

    /**
     * Constructs an element in-place.
     *
     * All iterators, references and pointers are invalidated.
     *
     * @param args The arguments to pass to the \c value_type constructor.
     * @returns an \c iterator to the inserted element.
     */
    template <typename... Args>
    iterator emplace(Args&&... args)
    {
        // We need the key, so just construct the item here
        return insert(value_type{ std::forward<Args>(args)... });
    }

    /**
     * Removes elements with the given key.
     *
     * References, pointers and iterators to the erased elements are invalidated. All other iterators, pointers and
     * references remain valid.
     *
     * @param key the key value of elements to remove
     * @returns the number of elements removed.
     */
    size_type erase(const key_type& key)
    {
        size_t count = 0;
        auto vt = this->internal_find(key);
        decltype(vt) next;
        for (; vt; vt = next)
        {
            next = this->_findnext(vt);
            this->internal_erase(vt);
            ++count;
        }
        return count;
    }

    /**
     * Removes all elements with key that compares equivalent to the given key.
     *
     * References, pointers and iterators to the erased elements are invalidated. All other iterators, pointers and
     * references remain valid.
     * @note This overload participates in overload resolution only if Hash and KeyEqual are both transparent. This
     * assumes that such Hash is callable with both `K` and `Key` type and that KeyEqual is transparent, which,
     * together, allows calling this function without constructing an instance of Key.
     * @param key A value of any type that can be transparently compared with a key denoting the elements to remove.
     * @returns the number of elements removed.
     */
    template <typename K,
              typename = std::enable_if_t<IsTransparent_v<K> && !std::is_convertible_v<K, const_iterator> &&
                                          !std::is_convertible_v<K, const_find_iterator>>>
    size_type erase(K&& key)
    {
        size_t count = 0;
        auto vt = this->internal_find(key);
        decltype(vt) next;
        for (; vt; vt = next)
        {
            next = this->_findnext(vt, key);
            this->internal_erase(vt);
            ++count;
        }
        return count;
    }

    /**
     * Returns the number of elements matching the specified key.
     *
     * @param key The key to check for.
     * @returns The number of elements with the given key.
     */
    size_type count(const key_type& key) const
    {
        return this->internal_count_multi(key);
    }

    /**
     * Returns the number of elements matching the specified key.
     * @note This overload participates in overload resolution only if Hash and KeyEqual are both transparent. This
     * assumes that such Hash is callable with both `K` and `Key` type and that KeyEqual is transparent, which,
     * together, allows calling this function without constructing an instance of Key.
     * @param key A value of any type that can be transparently compared with a key
     * @returns The number of elements with key that compares equivalent to @p key
     */
    template <typename K, typename = std::enable_if_t<IsTransparent_v<K>>>
    size_type count(const K& key) const
    {
        return this->internal_count_multi(key);
    }

#ifndef DOXYGEN_BUILD
    using Base::begin;
    using Base::cbegin;
    using Base::cend;
    using Base::end;

    using Base::capacity;
    using Base::empty;
    using Base::max_size;
    using Base::size;

    using Base::clear;
    using Base::erase;
    using Base::swap;

    using Base::contains;
    using Base::equal_range;
    using Base::find;

    using Base::rehash;
    using Base::reserve;

    using Base::get_allocator;
    using Base::hash_function;
    using Base::key_eq;
#endif
};

#ifndef DOXYGEN_BUILD
// Deduction guides
template <typename InputIt,
          typename Hash = std::hash<detail::KeyFromIt_t<InputIt>>,
          typename Pred = std::equal_to<detail::KeyFromIt_t<InputIt>>,
          size_t LoadFactorMax100 = kDefaultLoadFactor,
          typename Alloc = detail::AllocFromIt_t<InputIt>>
RHUnorderedMultimap(InputIt, InputIt, size_t = 0, Hash = Hash(), Pred = Pred(), Alloc = Alloc())
    -> RHUnorderedMultimap<detail::KeyFromIt_t<InputIt>, detail::MappedFromIt_t<InputIt>, Hash, Pred, LoadFactorMax100, Alloc>;

template <typename Key,
          typename T,
          typename Hash = std::hash<Key>,
          typename Pred = std::equal_to<Key>,
          size_t LoadFactorMax100 = kDefaultLoadFactor,
          typename Alloc = std::allocator<std::pair<const Key, T>>>
RHUnorderedMultimap(std::initializer_list<std::pair<Key, T>>, size_t = 0, Hash = Hash(), Pred = Pred(), Alloc = Alloc())
    -> RHUnorderedMultimap<Key, T, Hash, Pred, LoadFactorMax100, Alloc>;

template <typename InputIt, typename Alloc>
RHUnorderedMultimap(InputIt, InputIt, size_t, Alloc) -> RHUnorderedMultimap<detail::KeyFromIt_t<InputIt>,
                                                                            detail::MappedFromIt_t<InputIt>,
                                                                            std::hash<detail::KeyFromIt_t<InputIt>>,
                                                                            std::equal_to<detail::KeyFromIt_t<InputIt>>,
                                                                            kDefaultLoadFactor,
                                                                            Alloc>;

template <typename InputIt, typename Hash, typename Alloc>
RHUnorderedMultimap(InputIt, InputIt, size_t, Hash, Alloc)
    -> RHUnorderedMultimap<detail::KeyFromIt_t<InputIt>,
                           detail::MappedFromIt_t<InputIt>,
                           Hash,
                           std::equal_to<detail::KeyFromIt_t<InputIt>>,
                           kDefaultLoadFactor,
                           Alloc>;

template <typename Key, typename T, typename Alloc>
RHUnorderedMultimap(std::initializer_list<std::pair<Key, T>>, size_t, Alloc)
    -> RHUnorderedMultimap<Key, T, std::hash<Key>, std::equal_to<Key>, kDefaultLoadFactor, Alloc>;

template <typename Key, typename T, typename Hash, typename Alloc>
RHUnorderedMultimap(std::initializer_list<std::pair<Key, T>>, size_t, Hash, Alloc)
    -> RHUnorderedMultimap<Key, T, Hash, std::equal_to<Key>, kDefaultLoadFactor, Alloc>;
#endif

} // namespace carb::container
